<?php
session_start(); require 'config/database.php'; if(!isset($_SESSION['user'])){header('Location: login.php');exit;} $role=$_SESSION['user']['role'];
if($role==='student'){$q=$pdo->prepare('SELECT s.id,s.roll_no,u.name FROM students s JOIN users u ON u.id=s.user_id WHERE s.user_id=?');$q->execute([$_SESSION['user']['id']]);$student=$q->fetch();$fees=$student?$pdo->query('SELECT * FROM fee_challans WHERE student_id='.(int)$student['id'].' ORDER BY issue_date DESC')->fetchAll():[];} else {$fees=$pdo->query('SELECT f.*,s.roll_no,u.name FROM fee_challans f JOIN students s ON s.id=f.student_id JOIN users u ON u.id=s.user_id ORDER BY f.issue_date DESC')->fetchAll();}
$pageTitle='Fee Management';require 'includes/header.php';?><div class="container py-4"><div class="d-flex justify-content-between"><div><h2>Fee Challans</h2><p class="text-muted">View fee challans and payment status.</p></div><a href="dashboard.php" class="btn btn-outline-secondary">Portal</a></div><div class="card shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><?php if($role!=='student'):?><th>Student</th><?php endif;?><th>Challan</th><th>Purpose</th><th>Amount</th><th>Due Date</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($fees as $f):?><tr><?php if($role!=='student'):?><td><?=htmlspecialchars($f['roll_no'].' — '.$f['name'])?></td><?php endif;?><td><?=htmlspecialchars($f['challan_no'])?></td><td><?=htmlspecialchars($f['purpose'])?></td><td>Rs. <?=number_format($f['amount'],2)?></td><td><?=htmlspecialchars($f['due_date'])?></td><td><span class="badge <?= $f['status']==='paid'?'text-bg-success':'text-bg-warning' ?>"><?=htmlspecialchars($f['status'])?></span></td><td><a class="btn btn-sm btn-outline-primary" href="fee_receipt.php?id=<?=$f['id']?>">View / Print</a></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require 'includes/footer.php';?>
